CREATE FUNCTION guard_entitlement_usage() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$BEGIN IF (SELECT count(*) FROM public.rooms WHERE organization_id=NEW.organization_id AND archived_at IS NULL)>NEW.room_limit OR (SELECT count(*) FROM public.properties WHERE organization_id=NEW.organization_id AND archived_at IS NULL)>NEW.property_limit OR (SELECT count(*) FROM public.memberships WHERE organization_id=NEW.organization_id AND revoked_at IS NULL)>NEW.staff_limit THEN RAISE EXCEPTION 'USAGE_EXCEEDS_PLAN' USING ERRCODE='P0409';END IF;RETURN NEW;END $$;
CREATE TRIGGER protect_entitlement_usage BEFORE INSERT OR UPDATE OF room_limit,property_limit,staff_limit ON organization_entitlements FOR EACH ROW EXECUTE FUNCTION guard_entitlement_usage();REVOKE ALL ON FUNCTION guard_entitlement_usage() FROM PUBLIC;
